"""Load lossless opcode source components without changing their module identity.

This module deliberately has no PyBoy imports: the native build loads it before
PyBoy's extensions exist. Component hashes detect corruption, not authenticity.
"""
from __future__ import annotations

import ast
import hashlib
import linecache
import os
import re
import tempfile
from pathlib import Path

MANIFEST_NAME = "_opcodes_manifest.py"
_NAME = re.compile(r"opcode_components/(?:source|declarations)_[a-z]+_[0-9]{3}_[0-9a-f]{12}\.pxi\Z")
_KEYS = {"FORMAT_VERSION", "MAX_LINES", "SOURCE_SHA256", "DECLARATIONS_SHA256", "SOURCE_PARTS", "DECLARATION_PARTS"}


def _manifest(core):
    """Read only literal assignments; never execute a manifest as Python code."""
    path = Path(core) / MANIFEST_NAME
    tree = ast.parse(path.read_bytes().decode("utf-8"), filename=str(path))
    values = {}
    for node in tree.body:
        if not (isinstance(node, ast.Assign) and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Name)):
            raise ValueError("opcode manifest must contain literal assignments only")
        key = node.targets[0].id
        if key not in _KEYS or key in values:
            raise ValueError("unknown or duplicate opcode manifest key: " + key)
        values[key] = ast.literal_eval(node.value)
    if set(values) != _KEYS or values["FORMAT_VERSION"] != 1:
        raise ValueError("unsupported or incomplete opcode manifest")
    limit = values["MAX_LINES"]
    if type(limit) is not int or not 1 <= limit < 1000:
        raise ValueError("opcode component line bound must be below 1000")
    return values


def _join(core, entries, expected_hash, limit, prefix):
    if not isinstance(entries, tuple) or not entries:
        raise ValueError("opcode component manifest must be a nonempty tuple")
    if not isinstance(expected_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        raise ValueError("invalid opcode whole-source digest")
    chunks, seen = [], set()
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError("invalid opcode component entry")
        name, digest = entry
        if (not isinstance(name, str) or not _NAME.fullmatch(name)
                or not name.startswith("opcode_components/" + prefix + "_")
                or name in seen or not isinstance(digest, str)
                or not re.fullmatch(r"[0-9a-f]{64}", digest)):
            raise ValueError("invalid or duplicate opcode component path/hash")
        seen.add(name)
        path = Path(core) / name
        # Reject symlinks as well as traversal; a source snapshot is self-contained.
        if path.is_symlink() or path.parent.is_symlink():
            raise ValueError("opcode components cannot be symbolic links")
        data = path.read_bytes()
        if hashlib.sha256(data).hexdigest() != digest:
            raise ValueError("opcode component checksum mismatch: " + name)
        if len(data.decode("utf-8").splitlines()) > limit:
            raise ValueError("opcode component exceeds its line bound: " + name)
        chunks.append(data)
    result = b"".join(chunks)
    if hashlib.sha256(result).hexdigest() != expected_hash:
        raise ValueError("opcode reassembly checksum mismatch")
    return result


def declaration_facade(entries):
    return ("# Generated by opcodes_gen.py; do not edit.\n"
            + "".join('include "' + name + '"\n' for name, _ in entries)).encode("utf-8")


def read_sources(core):
    """Return exactly the pre-layout .py and .pxd bytes, failing closed on drift."""
    core = Path(core)
    values = _manifest(core)
    source = _join(core, values["SOURCE_PARTS"], values["SOURCE_SHA256"],
                   values["MAX_LINES"], "source")
    declarations = _join(core, values["DECLARATION_PARTS"], values["DECLARATIONS_SHA256"],
                         values["MAX_LINES"], "declarations")
    if (core / "opcodes.pxd").read_bytes() != declaration_facade(values["DECLARATION_PARTS"]):
        raise ValueError("opcode declaration facade disagrees with manifest")
    return source, declarations


def load_into(namespace):
    """Execute once in the original globals; preserve names, returns and tracebacks."""
    filename = namespace["__file__"]
    try:
        source, _ = read_sources(Path(filename).parent)
        text = source.decode("utf-8")
        code = compile(text, filename, "exec", dont_inherit=True)
    except (OSError, ValueError, SyntaxError) as exc:
        raise ImportError("cannot load generated opcode components: " + str(exc)) from exc
    # Keep inspect.getsource and tracebacks on the original logical source lines.
    linecache.cache[filename] = (len(source), None, text.splitlines(keepends=True), filename)
    exec(code, namespace)


def _write_if_changed(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_bytes() == data:
        return
    fd, temp = tempfile.mkstemp(prefix=".opcode-native-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def prepare_opcode_source(source, build_root="build/opcode-layout"):
    """Keep the Extension name unchanged; replace only its compiler input path."""
    path = Path(source)
    if path.as_posix() != "pyboy/core/opcodes.py":
        return source
    python_source, declarations = read_sources(path.parent)
    destination = Path(build_root) / "pyboy/core/opcodes.py"
    _write_if_changed(destination, python_source)
    _write_if_changed(destination.with_suffix(".pxd"), declarations)
    return str(destination)
